var test = require('tap').test
var once = require('../once.js')

test('once(fn)', function (t) {
  var f = 0
  function fn (g) {
    t.equal(f, 0)
    f ++
    return f + g + this
  }
  fn.ownProperty = {}
  var foo = once(fn)
  t.equal(fn.ownProperty, foo.ownProperty)
  t.notOk(foo.called)
  for (var i = 0; i < 1E3; i++) {
    t.same(f, i === 0 ? 0 : 1)
    var g = foo.call(1, 1)
    t.ok(foo.called)
    t.same(g, 3)
    t.same(f, 1)
  }
  t.end()
})

test('fn.once()', function (t) {
  once.proto()
  var f = 0
  function fn (g) {
    t.equal(f, 0)
    f ++
    return f + g + this
  }
  var foo = fn.once()
  t.notOk(foo.called)
  for (var i = 0; i < 1E3; i++) {
    t.same(f, i === 0 ? 0 : 1)
    var g = foo.call(1, 1)
    t.ok(foo.called)
    t.same(g, 3)
    t.same(f, 1)
  }
  t.end()
})

test('once.strict with named function', function (t) {
  var f = 0
  function fn (g) {
    t.equal(f, 0)
    f ++
    return f + g + this
  }
  fn.ownProperty = {}
  var foo = once.strict(fn)
  t.equal(fn.ownProperty, foo.ownProperty)
  t.notOk(foo.called)

  var g = foo.call(1, 1)
  t.ok(foo.called)
  t.same(g, 3)
  t.same(f, 1)

  try {
    foo.call(2, 2)
    t.fail('strict once should throw exception on second call')
  } catch (err) {
    t.ok(err instanceof Error)
    t.equal(err.message, "fn shouldn't be called more than once")
    t.end()
  }
})

test('fn.onceStrict()', function (t) {
  var f = 0
  function fn (g) {
    t.equal(f, 0)
    f ++
    return f + g + this
  }
  var foo = fn.onceStrict(fn)
  t.notOk(foo.called)

  var g = foo.call(1, 1)
  t.ok(foo.called)
  t.same(g, 3)
  t.same(f, 1)

  try {
